package config
import ("fmt"; "strings")
const CurrentMusicConfigVersion = 4
type MusicConfig struct { ConfigVersion int `json:"config_version"`; Enabled bool `json:"enabled"`; CommandEnabled bool `json:"command_enabled"`; CommandPrefix string `json:"command_prefix"`; QueueCapacity int `json:"queue_capacity"` }
func DefaultMusicConfig() MusicConfig { return MusicConfig{ConfigVersion:CurrentMusicConfigVersion,Enabled:true,CommandEnabled:true,CommandPrefix:"点歌",QueueCapacity:100} }
func MigrateMusicConfig(c MusicConfig)(MusicConfig,bool){if c.ConfigVersion>=CurrentMusicConfigVersion{return c,false};n:=DefaultMusicConfig();n.Enabled=c.Enabled;n.CommandEnabled=c.CommandEnabled;if strings.TrimSpace(c.CommandPrefix)!=""{n.CommandPrefix=c.CommandPrefix};if c.QueueCapacity>=1&&c.QueueCapacity<=1000{n.QueueCapacity=c.QueueCapacity};return n,true}
func(c MusicConfig)Validate()error{if c.ConfigVersion!=CurrentMusicConfigVersion{return fmt.Errorf("unsupported music configuration version %d",c.ConfigVersion)};if strings.TrimSpace(c.CommandPrefix)==""{return fmt.Errorf("music command prefix is required")};if len([]rune(c.CommandPrefix))>16{return fmt.Errorf("music command prefix is too long")};if c.QueueCapacity<1||c.QueueCapacity>1000{return fmt.Errorf("music queue capacity must be between 1 and 1000")};return nil}
func LoadMusicConfig(m *Manager)(MusicConfig,error){v,e:=LoadTyped[MusicConfig](m,"music.json",func(c MusicConfig)error{if c.ConfigVersion<CurrentMusicConfigVersion{return nil};return c.Validate()});if e!=nil{return MusicConfig{},e};n,changed:=MigrateMusicConfig(v);if !changed{return v,nil};if e:=SaveTyped(m,"music.json",n,func(c MusicConfig)error{return c.Validate()});e!=nil{return MusicConfig{},fmt.Errorf("migrate music configuration: %w",e)};return n,nil}
